struct Node { int l, r, cnt; } t[MAXNODES];    // 왼쪽·오른쪽 자식 번호, 이 구간에 든 값의 개수
int tot = 0;                                    // 노드 0은 '빈 트리'(자기 자신을 가리킴)
int add(int prev, int s, int e, int pos) {      // prev 버전에 값 pos를 하나 더한 새 버전의 루트
    int cur = ++tot; t[cur] = t[prev]; t[cur].cnt++;
    if (s == e) return cur;
    int m = (s + e) / 2;
    if (pos <= m) t[cur].l = add(t[prev].l, s, m, pos);
    else          t[cur].r = add(t[prev].r, m + 1, e, pos);
    return cur;                                  // 바뀌지 않은 쪽 자식은 prev와 공유한다
}
// root[i] = a[1..i]의 값을 모두 넣은 버전
int kth(int u, int v, int s, int e, int k) {    // a[l..r]에서 k번째로 작은 값: u = root[r], v = root[l-1]
    if (s == e) return s;
    int m = (s + e) / 2, leftCnt = t[t[u].l].cnt - t[t[v].l].cnt;
    if (k <= leftCnt) return kth(t[u].l, t[v].l, s, m, k);
    return kth(t[u].r, t[v].r, m + 1, e, k - leftCnt);
}

